@startuml
class Person {}
class Student extends Person {
  +name : string
  +email : string
}
class Tutor extends Person {
  +name : string
  +email : string
  +bankAccount : string
}
class Subject {}
class ExpertiseLevel {}
class Availability {
  +day : string
  +startTime : time
  +endTime : time
}
class TutoringOffer {
  +levelOfExpertise : ExpertiseLevel
  +hourlyPrice : float
}
class TutoringRequest {
  +level : ExpertiseLevel
  +targetDate : date
  +targetTime : time
}
class TutoringSession {
  +actualDate : date
  +actualTime : time
}
class Payment {
  +amount : float
  +method : string
}
class Award {
  +month : string
}

Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
Tutor "1" -- "*" TutoringOffer : offers
Subject "1" -- "*" TutoringOffer : for
TutoringOffer "1" -- "*" TutoringRequest : is subject of
TutoringRequest "0..1" -- "0..1" TutoringSession : becomes
TutoringSession "1" -- "1" Student : attended by
TutoringSession "1" -- "1" Tutor : attended by
TutoringSession "1" -- "0..1" TutoringSession : schedules follow-up
TutoringSession "1" -- "0..1" Payment : results in
Tutor "1" -- "*" Award : receives
Subject "1" -- "*" Award : for
@enduml

